# cli_commands.py

from task_storage import TaskStorage, Task

storage = TaskStorage()

def add_task(id, description):
    storage.add_task(Task(id, description))
    print(f"Task {id} added successfully.")

def mark_task_complete(task_id):
    try:
        storage.mark_task_complete(task_id)
        print(f"Task {task_id} marked as complete.")
    except (ValueError, KeyError) as e:
        print(e)

def list_tasks():
    for task in storage.tasks.values():
        status = "Complete" if task.completed else "Pending"
        print(f"{task.id}: {task.description} ({status})")
