# persistence.py

import json

def save_tasks(tasks):
    with open('tasks.json', 'w') as file:
        json.dump([vars(task) for task in tasks.values()], file)

def load_tasks():
    try:
        with open('tasks.json', 'r') as file:
            data = json.load(file)
            return {item['id']: Task(**item) for item in data}
    except FileNotFoundError:
        return {}
